import{_ as o,o as l,c as a,a3 as i}from"./chunks/framework.CezWKtOZ.js";const p=JSON.parse('{"title":"更新日志","description":"LiteGUI 版本变更","frontmatter":{"title":"更新日志","description":"LiteGUI 版本变更"},"headers":[],"relativePath":"changelog.md","filePath":"changelog.md","lastUpdated":1795881530000}'),t={name:"changelog.md"};function c(d,e,r,n,s,u){return l(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="更新日志" tabindex="-1">更新日志 <a class="header-anchor" href="#更新日志" aria-label="Permalink to &quot;更新日志&quot;">​</a></h1><h2 id="unreleased" tabindex="-1">Unreleased <a class="header-anchor" href="#unreleased" aria-label="Permalink to &quot;Unreleased&quot;">​</a></h2><p>monorepo 改造与包名调整：</p><ul><li>pnpm workspace：<code>packages/{core,litegui,tests}</code> + <code>apps/{demo,editor}</code></li><li>包目录改为 <code>packages/components</code>；包名最终为 <code>@gausszhou/litegui-components</code>（由 <code>@gausszhou/litegui</code> 改名）与 <code>@gausszhou/litegui-core</code>；<code>Inspector</code>、<code>Tree</code> 不再拆包，统一回到主包</li><li>产物从 <code>lib/</code> 改为各包 <code>dist/</code>；新增 ESLint、Typedoc API、size / verify-pack / pages 脚本</li><li>主包新增组件命名导出；<code>Inspector</code>、<code>Tree</code> 并入主包并恢复 <code>LiteGUI.Inspector/Tree</code>，UMD 仍为自包含单文件</li><li>修复二级菜单定位：与父项对齐、视口内自动翻转、清理旧子菜单</li><li>Web Components 标签统一为 <code>lg-*</code>（如 <code>lg-button</code>、<code>lg-panel</code>），事件名仍为 <code>litegui-*</code></li><li>新增 <code>@gausszhou/litegui-vue</code> Vue 3 绑定（Button / Checkbox / Slider / Panel / Dialog / Menu）</li><li>文档站改为每组件独立页：真实渲染 demo + 同源示例代码，<code>.lg-demo</code> 前缀样式隔离</li><li><code>Menu</code> / <code>ContextMenu</code> 新增 <code>container</code> 选项</li></ul><h2 id="_1-0-1" tabindex="-1">1.0.1 <a class="header-anchor" href="#_1-0-1" aria-label="Permalink to &quot;1.0.1&quot;">​</a></h2><p>测试与交互修复：</p><ul><li>Dragger 键盘/滚轮同步 <code>value</code></li><li>Tabs plus tab 插入修复</li><li>Area merge 修复</li><li>ContextMenu 子菜单引用</li><li>htmlEncode/htmlDecode 兼容 jsdom</li><li>单元测试 120 个、覆盖率约 72.8%</li></ul><h2 id="_1-0-0" tabindex="-1">1.0.0 <a class="header-anchor" href="#_1-0-0" aria-label="Permalink to &quot;1.0.0&quot;">​</a></h2><ul><li>Inspector/Tree 拆分到 <code>@gausszhou/litegui-experimental</code></li><li>HTML 安全默认值、escapeHTML、Table allowHTML</li><li>API 稳定性与弃用策略</li><li>Playwright Chrome/Firefox</li><li>主包体积下降</li></ul><h2 id="_0-2-0" tabindex="-1">0.2.0 <a class="header-anchor" href="#_0-2-0" aria-label="Permalink to &quot;0.2.0&quot;">​</a></h2><ul><li>主题 token 与亮/暗主题</li><li>基础可访问性</li><li>按组件导出</li><li>VitePress 文档站</li></ul><h2 id="_0-1-0" tabindex="-1">0.1.0 <a class="header-anchor" href="#_0-1-0" aria-label="Permalink to &quot;0.1.0&quot;">​</a></h2><ul><li>核心组件、core 抽取、构建与测试基线。</li></ul><p>完整文件：<a href="https://github.com/gausszhou/litegui/blob/master/CHANGELOG.md" target="_blank" rel="noreferrer">CHANGELOG.md</a></p>',14)])])}const g=o(t,[["render",c]]);export{p as __pageData,g as default};
